digest=lambda data:hashlib.sha256(data).hexdigest()

def transform(text):
    if text!=ORIGINAL:raise ValueError('Unreviewed map_file_generator preimage')
    return REPLACEMENT

def apply(repo):
    def git(*args):return subprocess.check_output(['git',*args],cwd=repo)
    if git('rev-parse','HEAD').decode().strip()!=HEAD:raise ValueError('Unapproved system/update_engine HEAD')
    if git('ls-files','--others','--exclude-standard').strip():raise ValueError('Untracked system/update_engine sources')
    if git('diff','--cached','--name-only').strip():raise ValueError('Staged system/update_engine changes')
    if not set(git('diff','--name-only','HEAD').decode().splitlines()).issubset({FILE}):raise ValueError('Unrelated system/update_engine changes')
    path=repo/FILE
    if path.is_symlink() or not path.is_file():raise ValueError('Unsafe Makefile source path')
    original=git('show','HEAD:'+FILE)
    if digest(original)!=PRE_FILE_SHA:raise ValueError('Makefile baseline mismatch')
    desired=transform(original.decode()).encode()
    if digest(desired)!=POST_FILE_SHA:raise ValueError('Makefile reviewed postimage mismatch')
    current=path.read_bytes()
    if digest(current) not in (PRE_FILE_SHA,OLD_FILE_SHA,POST_FILE_SHA):raise ValueError('Unreviewed Makefile content')
    changed=current!=desired
    subprocess.run(['git','config','--local','core.abbrev','40'],cwd=repo,check=True)
    if changed:path.write_bytes(desired)
    if digest(git('diff','--binary','HEAD'))!=POST_PATCH_SHA:
        if changed:path.write_bytes(current)
        raise ValueError('Full system/update_engine patch mismatch')
    patch=''.join(difflib.unified_diff(current.decode().splitlines(True),desired.decode().splitlines(True),fromfile='a/'+FILE,tofile='b/'+FILE))
    return changed,patch,POST_PATCH_SHA

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--update-engine',type=Path,required=True);ap.add_argument('--patch-out',type=Path,required=True);ap.add_argument('--report-out',type=Path,required=True);args=ap.parse_args()
    try:changed,patch,sha=apply(args.update_engine)
    except (ValueError,subprocess.CalledProcessError) as exc:raise SystemExit('LEGACY_MAP_GENERATOR_COMPAT_FAIL='+str(exc))
    args.patch_out.write_text(patch)
    report='LEGACY_MAP_GENERATOR_COMPAT_STATE='+('APPLIED' if changed else 'ALREADY_APPLIED')+f'\nCHANGED_FILES={int(changed)}\nUPDATE_ENGINE_PATCH_SHA256={sha}\nLEGACY_MAP_GENERATOR_COMPAT=PASS\n'
    args.report_out.write_text(report);print(report,end='')

if __name__=='__main__':main()
